var $;

export function contactMain(jquery) {
  $ = jquery;

  $("#ajax-contact-form").on("submit", function (e) {
    // 1. Ferma il ricaricamento della pagina
    e.preventDefault();

    var $form = $(this);
    var $btn = $("#form-submit-btn");
    var $btnText = $btn.find(".btn-text");
    var $btnLoader = $btn.find(".btn-loader");
    var $errorMessage = $("#form-error-message");
    var $successMessage = $("#form-success-message");
    var actionUrl = $form.attr("action");

    var formData = $form.serialize();

    // 2. UI: Disattiva il form e mostra "Invio in corso..."
    $form.addClass("disabled"); // Abbassa opacità
    $form.find("input, textarea").prop("disabled", true); // Disabilita campi
    $btn.prop("disabled", true); // Disabilita bottone
    $btnText.hide();
    $btnLoader.show(); // Mostra spinner
    $errorMessage.hide();

    // 3. Chiamata AJAX
    $.ajax({
      url: actionUrl,
      method: "POST",
      data: formData,
      dataType: "json",
      accepts: "application/json", // FORZIAMO la richiesta di JSON
      success: function (data) {
        // 4. SUCCESSO
        $form.slideUp(500, function () {
          $successMessage.fadeIn();
        });
      },
      error: function (err) {
        // Gestione errori migliorata
        console.log(err);

        // Se l'invio AJAX fallisce ancora (es. controllo spam severo),
        // facciamo il fallback all'invio classico così l'utente può risolvere il captcha.
        $form.off("submit");
        $form.removeClass("disabled");
        $form.find("input, textarea").prop("disabled", false);
        $btn.prop("disabled", false);
        $form[0].submit(); // Invio nativo HTML
      },
    });
  });
}
