var $;

export class MenuLanguageSwitcher {
  constructor() {}

  init(jquery) {
    $ = jquery;

    this.$dropdownButton = $(".dropdown-button");
    this.$dropdownButtonImg = $(".dropdown-button img"); // Cache dell'immagine del bottone
    this.$dropdownContent = $(".dropdown-content"); // Selettore contenitore
    this.$dropdownLinks = $(".dropdown-content a"); // Selettore link
    this.$document = $(document);

    // 1. AUTO-SELEZIONE ALL'AVVIO
    // Controlliamo l'URL per decidere quale bandierina mostrare nel bottone
    this.#setInitialVisualState();

    this.initEvents();
  }

  initEvents() {
    this.$dropdownButton.on("click", (event) =>
      this.#dropdownButtonClickCallback(event),
    );

    this.$dropdownLinks.on("click", (event) =>
      this.#dropdownContentLinksClickCallback(event),
    );

    this.$document.on("click", () => this.#documentClickCallback());
  }

  // Imposta la bandierina corretta appena si carica la pagina
  #setInitialVisualState() {
    const isEnglish = window.location.href.indexOf("/en/") > -1;

    // Cerchiamo nel dropdown l'elemento che corrisponde alla lingua corrente
    let $targetLink;

    if (isEnglish) {
      $targetLink = this.$dropdownLinks.filter('[data-value="en"]');
    } else {
      $targetLink = this.$dropdownLinks.filter('[data-value="it"]');
    }

    // Se troviamo il link, copiamo la sua immagine nel bottone principale
    if ($targetLink.length > 0) {
      // MODIFICA: Cerchiamo il tag <img> all'interno del link <a> e prendiamo il suo src reale
      const $imgInside = $targetLink.find("img");
      const flagSrc = $imgInside.attr("src");

      const flagAlt = isEnglish ? "English" : "Italiano";

      this.$dropdownButtonImg.attr("src", flagSrc);
      this.$dropdownButtonImg.attr("alt", flagAlt);
    }
  }

  #dropdownButtonClickCallback(event) {
    event.stopPropagation();
    // Usiamo toggleClass per semplicità se hai le classi CSS pronte,
    // altrimenti la logica show/hide manuale va bene:
    if (this.$dropdownContent.hasClass("display-none")) {
      this.#showMenuLanguageSwitcher();
    } else {
      this.#hideMenuLanguageSwitcher();
    }
  }

  #hideMenuLanguageSwitcher() {
    this.$dropdownContent
      .removeClass("display-block-with-fading")
      .addClass("display-none");
    $(".dropdown-button i")
      .removeClass("fa-arrow-up")
      .addClass("fa-arrow-down");
  }

  #showMenuLanguageSwitcher() {
    this.$dropdownContent
      .removeClass("display-none")
      .addClass("display-block-with-fading");
    $(".dropdown-button i")
      .removeClass("fa-arrow-down")
      .addClass("fa-arrow-up");
  }

#dropdownContentLinksClickCallback(event) {
    event.preventDefault();

    // 1. Recupera la lingua target dal link cliccato ("it" o "en")
    const $clickedLink = $(event.target).closest("a");
    const targetLang = $clickedLink.attr("data-value"); 
    
    // 2. Legge l'URL completo attuale visibile nel browser
    const currentUrl = window.location.href;
    
    let newUrl = "";

    // 3. Logica di sostituzione e troncamento dell'URL
    if (currentUrl.indexOf("/it/") > -1) {
        // Se l'URL attuale contiene /it/
        // Base diventa: "https://username.github.io/apuliablue"
        const baseUrl = currentUrl.split("/it/")[0];
        newUrl = baseUrl + "/" + targetLang + "/"; // Aggiunge /en/ (o /it/) alla fine
    } 
    else if (currentUrl.indexOf("/en/") > -1) {
        // Se l'URL attuale contiene /en/
        const baseUrl = currentUrl.split("/en/")[0];
        newUrl = baseUrl + "/" + targetLang + "/";
    } 
    else {
        // FALLBACK DI SICUREZZA se non c'è né /it/ né /en/
        newUrl = "/" + targetLang + "/";
    }

    // 4. Redirect
    window.location.href = newUrl;
  }

  #documentClickCallback() {
    // Chiude il menu se si clicca fuori
    if (!this.$dropdownContent.hasClass("display-none")) {
      this.#hideMenuLanguageSwitcher();
    }
  }
}
